import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { drizzle } from "drizzle-orm/node-postgres";
import { migrate } from "drizzle-orm/node-postgres/migrator";
import { readMigrationFiles } from "drizzle-orm/migrator";
import type pg from "pg";
import type { Logger } from "pino";

/** Checked-in SQL migrations generated by drizzle-kit (`pnpm db:generate`). */
export const MIGRATIONS_FOLDER = join(dirname(fileURLToPath(import.meta.url)), "..", "..", "drizzle");
const MIGRATIONS_SCHEMA = "drizzle";
const MIGRATIONS_TABLE = "__drizzle_migrations";
/** Arbitrary, stable advisory lock key so concurrent control-plane starts migrate one at a time. */
const MIGRATION_LOCK_KEY = 0x0b10cf09;

/** Applies pending migrations while holding a session-level advisory lock. */
export async function runMigrations(pool: pg.Pool, logger: Logger, folder = MIGRATIONS_FOLDER): Promise<void> {
  const client = await pool.connect();
  try {
    await client.query("SELECT pg_advisory_lock($1)", [MIGRATION_LOCK_KEY]);
    try {
      const started = Date.now();
      await migrate(drizzle(client), {
        migrationsFolder: folder,
        migrationsSchema: MIGRATIONS_SCHEMA,
        migrationsTable: MIGRATIONS_TABLE,
      });
      logger.info({ ms: Date.now() - started }, "database migrations applied");
    } finally {
      await client.query("SELECT pg_advisory_unlock($1)", [MIGRATION_LOCK_KEY]);
    }
  } finally {
    client.release();
  }
}

export interface MigrationStatus {
  expected: number;
  applied: number;
  upToDate: boolean;
}

/** Compares checked-in migrations with the migrations table (used by `/readyz`). */
export async function migrationStatus(pool: pg.Pool, folder = MIGRATIONS_FOLDER): Promise<MigrationStatus> {
  const expected = readMigrationFiles({ migrationsFolder: folder });
  const res = await pool.query<{ hash: string }>(
    `SELECT hash FROM "${MIGRATIONS_SCHEMA}"."${MIGRATIONS_TABLE}"`,
  );
  const applied = new Set(res.rows.map((r) => r.hash));
  const upToDate = expected.every((m) => applied.has(m.hash));
  return { expected: expected.length, applied: res.rows.length, upToDate };
}
